// Command widgets is the kwxGO port of the wxWidgets "widgets" sample
// (samples/widgets/widgets.cpp and widgets.h).
//
// The sample is a wxTreebook whose pages each demonstrate one widget. A log
// window below the book shows the widget events generated by the current page,
// and the menus let the user change the attributes (tooltip, colours, font,
// enabled, shown, border, variant, layout direction, cursor) of the widget(s)
// on the current page.
package main

import (
	"fmt"
	"reflect"
	"runtime"
	"sort"
	"strings"
	"unsafe"

	"github.com/KeyWorksRW/kwxGO/wx"
)

// ---------------------------------------------------------------------------
// Control ids -- the enum at widgets.cpp:68. The numbers are part of the
// contract: the "Page" menu items are Widgets_GoToPage + <book index>, and the
// border/variant radio ranges are matched by BindIdRange.
// ---------------------------------------------------------------------------

const (
	idClearLog = 100 + iota
	idQuit

	idBookCtrl

	idSetTooltip
	idSetFgColour
	idSetBgColour
	idSetPageBg
	idSetFont
	idEnable
	idShow

	idBorderNone
	idBorderStatic
	idBorderSimple
	idBorderRaised
	idBorderSunken
	idBorderDouble
	idBorderDefault

	idVariantNormal
	idVariantSmall
	idVariantMini
	idVariantLarge

	idLayoutDirection

	idGlobalBusyCursor
	idBusyCursor
)

const (
	idGoToPage     = 124
	idGoToPageLast = 124 + 100
)

const (
	idTextEntryBegin = 225 + iota
	idAutoCompleteFixed
	idAutoCompleteFilenames
	idAutoCompleteDirectories
	idAutoCompleteCustom
	idAutoCompleteKeyLength
	idTextEntrySetHint
	idTextEntryEnd
)

const idDisableAutoComplete = idTextEntryBegin

const (
	idThemeLight = 233 + iota
	idThemeDark
	idThemeSystem
)

// Page categories, widgets.h:51. Both the enum order and the bit values matter:
// IMPLEMENT_WIDGETS_PAGE always ORs in ALL_CTRLS.
const (
	pageNative = 1 << iota
	pageGeneric
	pagePicker
	pageCombo
	pageWithItems
	pageEditable
	pageBook
	pageAll
)

var widgetCategories = [...]string{
	"Native",
	"Generic",
	"Pickers",
	"Comboboxes",
	"With items",
	"Editable",
	"Books",
	"All controls",
}

// wxApp::Appearance and wxApp::AppearanceResult enumerators are exported by the
// binding as package constants.

const (
	maxPages = 8

	nativeCtrls   = 1 << 0
	genericCtrls  = 1 << 1
	pickerCtrls   = 1 << 2
	comboCtrls    = 1 << 3
	itemsCtrls    = 1 << 4
	editableCtrls = 1 << 5
	bookCtrls     = 1 << 6
	allCtrls      = 1 << 7
)

// ---------------------------------------------------------------------------
// WidgetAttributes -- widgets.h:87
// ---------------------------------------------------------------------------

type widgetAttributes struct {
	tooltip   string
	font      *wx.Font
	colFg     *wx.Colour
	colBg     *wx.Colour
	colPageBg *wx.Colour

	enabled bool
	show    bool

	dir     int
	variant int
	cursor  unsafe.Pointer

	// m_defaultFlags: currently only contains border flags
	defaultFlags int
}

func newWidgetAttributes() *widgetAttributes {
	return &widgetAttributes{
		tooltip:      "This is a tooltip",
		enabled:      true,
		show:         true,
		dir:          wx.Layout_Default,
		variant:      wx.WINDOW_VARIANT_NORMAL,
		defaultFlags: wx.BORDER_DEFAULT,
	}
}

// ---------------------------------------------------------------------------
// Page plumbing
// ---------------------------------------------------------------------------

// pageInfo mirrors WidgetsPageInfo: a label, the category mask and a
// constructor. The list is kept sorted by label, exactly like the C++ linked
// list that inserts each new page in label order.
type pageInfo struct {
	label string
	cats  int
	ctor  func(book unsafe.Pointer) *pageBase
}

// pageRegistry is filled by the init() in each page file.
var pageRegistry []pageInfo

func registerPage(label string, cats int, ctor func(book unsafe.Pointer) *pageBase) {
	pageRegistry = append(pageRegistry, pageInfo{label: label, cats: allCtrls | cats, ctor: ctor})
}

// pageBase is the Go equivalent of the non-virtual part of WidgetsPage: the
// scrolled window, the lazy content creation and the notification flag.
type pageBase struct {
	win *wx.ScrolledWindow

	// lastRow is the row sizer built by the most recent row helper call.
	lastRow *wx.BoxSizer

	// label and icon are set by the page constructor; the label is the book
	// page label and the icon is its 16x16 (or 32x32) SVG asset.
	label    string
	iconPath string
	iconW    int
	iconH    int

	created        bool
	notifyRecreate bool

	content    func(f *widgetsFrame)
	getWidgets func() []unsafe.Pointer
	getEntry   func() unsafe.Pointer
	recreate   func(f *widgetsFrame)
}

// newPageBase creates the page window: WidgetsPage::WidgetsPage().
func newPageBase(book unsafe.Pointer) *pageBase {
	win := wx.NewScrolledWindow(book, wx.ID_ANY, -1, -1, -1, -1,
		wx.CLIP_CHILDREN|wx.TAB_TRAVERSAL)
	if win == nil {
		return nil
	}
	return &pageBase{win: win}
}

func (p *pageBase) createContent(f *widgetsFrame) {
	if p.content != nil {
		p.content(f)
	}
}

func (p *pageBase) widgets() []unsafe.Pointer {
	if p.getWidgets != nil {
		return p.getWidgets()
	}
	return nil
}

func (p *pageBase) textEntry() unsafe.Pointer {
	if p.getEntry != nil {
		return p.getEntry()
	}
	return nil
}

func (p *pageBase) recreateWidget(f *widgetsFrame) {
	if p.recreate != nil {
		p.recreate(f)
	}
}

// notifyWidgetRecreation is WidgetsPage::NotifyWidgetRecreation(): apply the
// current attributes to the recreated widget and start logging its events.
func (p *pageBase) notifyWidgetRecreation(f *widgetsFrame, widget unsafe.Pointer) {
	if !p.notifyRecreate {
		return
	}
	f.setUpWidget(p)
	f.connectToWidgetEvents(widget)
}

// ---------------------------------------------------------------------------
// Frame state -- the WidgetsFrame members
// ---------------------------------------------------------------------------

type widgetsFrame struct {
	frame *wx.Frame
	panel *wx.Panel

	book    *wx.Treebook
	images  *wx.BitmapBundleArray
	bundles []*wx.BitmapBundle

	lboxLog *wx.ListBox

	menuBar      *wx.MenuBar
	menuWidget   *wx.Menu
	menuText     *wx.Menu
	menuPages    *wx.Menu
	menuTheme    *wx.Menu
	menuBorders  *wx.Menu
	menuVariants *wx.Menu

	// pages in book order; pages[0..7] are the category nodes, the rest are
	// the actual pages.
	pages    []*pageBase
	bookPage []int // page index -> index into pages, -1 for a category node

	attrs *widgetAttributes

	// logWindow replaces LboxLogger: C++ redirects wxLog to the listbox; the
	// port writes the same messages here directly while the frame is alive.
	logWindow bool

	// s_hint of OnSetHint
	hint string

	curPage *pageBase
}

// ---------------------------------------------------------------------------
// Application
// ---------------------------------------------------------------------------

func main() {
	wx.Run(func() bool {
		wx.SetVendorName("wxWidgets_Samples")

		f := newWidgetsFrame("wxMSW widgets demo")
		if f == nil {
			return false
		}

		f.frame.Show()
		wx.SetTopWindow(f.frame.Ptr())
		f.logWindow = true
		return true
	})
}

// newWidgetsFrame is WidgetsFrame::WidgetsFrame().
func newWidgetsFrame(title string) *widgetsFrame {
	f := &widgetsFrame{attrs: newWidgetAttributes(), hint: "Type here"}

	f.frame = wx.NewFrame(nil, wx.ID_ANY, title, -1, -1, -1, -1, wx.DEFAULT_FRAME_STYLE)
	if f.frame == nil {
		return nil
	}

	f.setIcon()
	f.buildMenus()

	f.panel = wx.NewPanel(f.frame.Ptr(), wx.ID_ANY, -1, -1, -1, -1, 0)
	if f.panel == nil {
		return nil
	}

	sizerTop := wx.NewBoxSizer(wx.VERTICAL)
	if sizerTop == nil {
		return nil
	}

	f.book = wx.NewTreebook(f.panel.Ptr(), idBookCtrl, -1, -1, 900, 500, wx.BK_DEFAULT)
	if f.book == nil {
		return nil
	}

	f.initBook()

	// The theme menu is appended after the book is initialised.
	f.menuTheme = wx.NewMenu("", 0)
	f.menuTheme.AppendRadioItem(idThemeSystem, "&System", "")
	f.menuTheme.AppendRadioItem(idThemeLight, "&Light", "")
	f.menuTheme.AppendRadioItem(idThemeDark, "&Dark", "")
	f.menuBar.Append(f.menuTheme.Ptr(), "T&heme")

	// the lower one only has the log listbox and a button to clear it
	box := wx.NewStaticBox(f.panel.Ptr(), wx.ID_ANY, "&Log window", -1, -1, -1, -1, 0)
	if box == nil {
		return nil
	}
	sizerDown := wx.NewStaticBoxSizer(box.Ptr(), wx.VERTICAL)
	if sizerDown == nil {
		return nil
	}

	f.lboxLog = wx.NewListBox(box.Ptr(), wx.ID_ANY, -1, -1, -1, -1, nil, 0)
	if f.lboxLog == nil {
		return nil
	}
	addWin(sizerDown, f.lboxLog.Ptr(), 1, func(sf *wx.SizerFlags) {
		sf.Expand()
		sf.Border(wx.ALL)
	})
	sizerDown.SetMinSize(100, 150)

	sizerBtns := wx.NewBoxSizer(wx.HORIZONTAL)
	if sizerBtns == nil {
		return nil
	}
	clearLog := wx.NewButton(box.Ptr(), idClearLog, "Clear &log", -1, -1, -1, -1, 0)
	if clearLog == nil {
		return nil
	}
	addWin(sizerBtns, clearLog.Ptr(), 0, nil)
	addSpacer(sizerBtns, 10)
	exitBtn := wx.NewButton(box.Ptr(), idQuit, "E&xit", -1, -1, -1, -1, 0)
	if exitBtn == nil {
		return nil
	}
	addWin(sizerBtns, exitBtn.Ptr(), 0, nil)
	addSub(sizerDown, sizerBtns.Ptr(), 0, func(sf *wx.SizerFlags) {
		sf.Border(wx.ALL)
		sf.Right()
	})

	// put everything together
	addWin(sizerTop, f.book.Ptr(), 1, func(sf *wx.SizerFlags) {
		sf.Expand()
		sf.DoubleBorder(wx.LEFT | wx.RIGHT)
	})
	addSpacer(sizerTop, 5)
	addSub(sizerTop, sizerDown.Ptr(), 0, func(sf *wx.SizerFlags) {
		sf.Expand()
		sf.DoubleBorder(wx.ALL & ^wx.TOP)
	})

	f.panel.SetSizer(sizerTop.Ptr(), false)

	size := f.panel.GetBestSize()
	f.frame.SetClientSize(size.Width, size.Height)
	f.frame.SetMinClientSize(size.Width, size.Height)

	f.bindEvents(clearLog, exitBtn)
	return f
}

// setIcon is SetIcon(wxICON(sample)); the icon is the SVG rendition of
// sample.xpm, loaded from the sample directory.
func (f *widgetsFrame) setIcon() {
	bundle := wx.BitmapBundle_FromSVGFile("sample.svg", 32, 32)
	if bundle == nil || !bundle.IsOk() {
		return
	}
	bitmap := bundle.GetBitmap(32, 32)
	if bitmap == nil {
		return
	}
	defer bitmap.Delete()

	icon := wx.NewIconDefault()
	if icon == nil {
		return
	}
	icon.CopyFromBitmap(bitmap.Ptr())
	if icon.IsOk() {
		f.frame.SetIcon(icon.Ptr())
	}
	icon.Delete()
}

// buildMenus creates the menu bar up to (but excluding) the Page and Theme
// menus, which are added later.
func (f *widgetsFrame) buildMenus() {
	f.menuBar = wx.NewMenuBar(0)
	if f.menuBar == nil {
		return
	}

	f.menuWidget = wx.NewMenu("", 0)
	f.menuWidget.Append(idSetTooltip, "Set &tooltip...\tCtrl-T", "", false)
	f.menuWidget.AppendSeparator()
	f.menuWidget.Append(idSetFgColour, "Set &foreground...\tCtrl-F", "", false)
	f.menuWidget.Append(idSetBgColour, "Set &background...\tCtrl-B", "", false)
	f.menuWidget.Append(idSetPageBg, "Set &page background...\tShift-Ctrl-B", "", false)
	f.menuWidget.Append(idSetFont, "Set f&ont...\tCtrl-O", "", false)
	f.menuWidget.AppendCheckItem(idEnable, "&Enable/disable\tCtrl-E", "")
	f.menuWidget.AppendCheckItem(idShow, "Show/Hide", "")

	f.menuBorders = wx.NewMenu("", 0)
	f.menuBorders.AppendRadioItem(idBorderDefault, "De&fault\tCtrl-Shift-9", "")
	f.menuBorders.AppendRadioItem(idBorderNone, "&None\tCtrl-Shift-0", "")
	f.menuBorders.AppendRadioItem(idBorderSimple, "&Simple\tCtrl-Shift-1", "")
	f.menuBorders.AppendRadioItem(idBorderDouble, "&Double\tCtrl-Shift-2", "")
	f.menuBorders.AppendRadioItem(idBorderStatic, "Stati&c\tCtrl-Shift-3", "")
	f.menuBorders.AppendRadioItem(idBorderRaised, "&Raised\tCtrl-Shift-4", "")
	f.menuBorders.AppendRadioItem(idBorderSunken, "S&unken\tCtrl-Shift-5", "")
	f.menuWidget.AppendSubMenu(f.menuBorders.Ptr(), "Set &border", "")

	f.menuVariants = wx.NewMenu("", 0)
	f.menuVariants.AppendRadioItem(idVariantMini, "&Mini\tCtrl-Shift-6", "")
	f.menuVariants.AppendRadioItem(idVariantSmall, "&Small\tCtrl-Shift-7", "")
	f.menuVariants.AppendRadioItem(idVariantNormal, "&Normal\tCtrl-Shift-8", "")
	f.menuVariants.AppendRadioItem(idVariantLarge, "&Large\tCtrl-Shift-9", "")
	f.menuWidget.AppendSubMenu(f.menuVariants.Ptr(), "Set &variant", "")

	f.menuWidget.AppendSeparator()
	f.menuWidget.AppendCheckItem(idLayoutDirection, "Toggle &layout direction\tCtrl-L", "")
	f.menuWidget.Check(idLayoutDirection, f.frame.GetLayoutDirection() == wx.Layout_RightToLeft)

	f.menuWidget.AppendSeparator()
	f.menuWidget.AppendCheckItem(idGlobalBusyCursor, "Toggle &global busy cursor\tCtrl-Shift-U", "")
	f.menuWidget.AppendCheckItem(idBusyCursor, "Toggle b&usy cursor\tCtrl-U", "")

	f.menuWidget.AppendSeparator()
	f.menuWidget.Append(wx.ID_EXIT, "&Quit\tCtrl-Q", "", false)
	f.menuBar.Append(f.menuWidget.Ptr(), "&Widget")

	f.menuText = wx.NewMenu("", 0)
	f.menuText.AppendRadioItem(idDisableAutoComplete, "&Disable auto-completion", "")
	f.menuText.AppendRadioItem(idAutoCompleteFixed, "Fixed-&list auto-completion", "")
	f.menuText.AppendRadioItem(idAutoCompleteFilenames, "&Files names auto-completion", "")
	f.menuText.AppendRadioItem(idAutoCompleteDirectories, "&Directories names auto-completion", "")
	f.menuText.AppendRadioItem(idAutoCompleteCustom, "&Custom auto-completion", "")
	f.menuText.AppendRadioItem(idAutoCompleteKeyLength, "Custom with &min length", "")
	f.menuText.AppendSeparator()
	f.menuText.Append(idTextEntrySetHint, "Set help &hint", "", false)
	f.menuBar.Append(f.menuText.Ptr(), "&Text")

	f.frame.SetMenuBar(f.menuBar.Ptr())

	f.menuBar.Check(idEnable, true)
	f.menuBar.Check(idShow, true)
	f.menuBar.Check(idVariantNormal, true)
}

// initBook is WidgetsFrame::InitBook().
func (f *widgetsFrame) initBook() {
	f.images = wx.NewBitmapBundleArray()
	if f.images == nil {
		return
	}

	// imageList[0] is the sample icon.
	if bundle := loadBundle("sample.svg", 32, 32); bundle != nil {
		f.images.Add(bundle.Ptr())
		f.bundles = append(f.bundles, bundle)
	}

	// The C++ code creates every page first (the image list must be complete)
	// and only then adds them to the book.
	sort.Slice(pageRegistry, func(i, j int) bool {
		return pageRegistry[i].label < pageRegistry[j].label
	})

	perCat := make([][]*pageBase, maxPages)
	f.menuPages = wx.NewMenu("", 0)

	nPage := 0
	for cat := 0; cat < maxPages; cat++ {
		nPage++ // increase for parent page

		for _, info := range pageRegistry {
			if info.cats&(1<<cat) == 0 {
				continue
			}

			page := info.ctor(f.book.Ptr())
			if page == nil {
				continue
			}
			page.label = info.label
			perCat[cat] = append(perCat[cat], page)

			// WidgetsPage::WidgetsPage() pushes the page icon into the image
			// list, so the bundle order follows the construction order.
			if bundle := loadBundle(page.iconPath, page.iconW, page.iconH); bundle != nil {
				f.images.Add(bundle.Ptr())
				f.bundles = append(f.bundles, bundle)
			}

			// the C++ sample appends the "Page" menu entries only while it is
			// walking the ALL_PAGE category, but counts every page so the ids
			// stay equal to the book page index.
			if cat == maxPages-1 {
				f.menuPages.AppendRadioItem(idGoToPage+nPage, info.label, "")
			}
			nPage++
		}
	}

	f.menuBar.Append(f.menuPages.Ptr(), "&Page")

	f.book.SetImages(f.images.Ptr())

	imageID := 1
	for cat := 0; cat < maxPages; cat++ {
		f.pages = append(f.pages, nil) // category node has no page object
		f.book.AddPage(nil, widgetCategories[cat], false, 0)

		for _, page := range perCat[cat] {
			f.pages = append(f.pages, page)
			f.book.AddSubPage(page.win.Ptr(), page.label, false, imageID)
			imageID++
		}
	}

	f.book.Bind(wx.EVT_TREEBOOK_PAGE_CHANGING, func(evt *wx.Event) {
		f.onPageChanging(evt)
	})
	f.book.Bind(wx.EVT_TREEBOOK_PAGE_CHANGED, func(evt *wx.Event) {
		f.onPageChanged(evt)
	})

	if f.book.GetCurrentPage() == nil {
		f.book.SetSelection(1)
	}
}

// loadBundle loads one SVG asset as a bitmap bundle owned by the sample.
func loadBundle(path string, w, h int) *wx.BitmapBundle {
	if path == "" {
		return nil
	}
	bundle := wx.BitmapBundle_FromSVGFile(path, w, h)
	if bundle == nil || !bundle.IsOk() {
		return nil
	}
	return bundle
}

// ---------------------------------------------------------------------------
// Current page and attributes
// ---------------------------------------------------------------------------

func (f *widgetsFrame) currentPage() *pageBase {
	p := f.book.GetCurrentPage()
	if p == nil {
		return nil
	}
	for _, page := range f.pages {
		if page != nil && page.win != nil && page.win.Ptr() == p {
			return page
		}
	}
	return nil
}

// setUpWidget is WidgetsPage::SetUpWidget() applied to the current page.
func (f *widgetsFrame) setUpWidget(p *pageBase) {
	if p == nil {
		return
	}

	for _, handle := range p.widgets() {
		if handle == nil {
			continue
		}
		w := wx.WindowFromPtr(handle)
		if w == nil {
			continue
		}

		w.SetToolTip(f.attrs.tooltip)

		if f.attrs.font != nil && f.attrs.font.IsOk() {
			w.SetFont(f.attrs.font.Ptr())
		}
		if f.attrs.colFg != nil && f.attrs.colFg.IsOk() {
			w.SetForegroundColour(f.attrs.colFg.Ptr())
		}
		if f.attrs.colBg != nil && f.attrs.colBg.IsOk() {
			w.SetBackgroundColour(f.attrs.colBg.Ptr())
		}
		if f.attrs.dir != wx.Layout_Default {
			w.SetLayoutDirection(f.attrs.dir)
		}
		w.Enable(f.attrs.enabled)
		if f.attrs.show {
			w.Show()
		} else {
			w.Hide()
		}
		// a nil cursor means wxNullCursor: reset the widget to the default cursor
		cursor := f.attrs.cursor
		if cursor == nil {
			cursor = wx.Null_Cursor()
		}
		if cursor != nil {
			w.SetCursor(cursor)
		}
		w.SetWindowVariant(f.attrs.variant)
		w.Refresh(true)
	}

	if f.attrs.colPageBg != nil && f.attrs.colPageBg.IsOk() {
		pageWin := wx.WindowFromPtr(p.win.Ptr())
		if pageWin != nil {
			pageWin.SetBackgroundColour(f.attrs.colPageBg.Ptr())
			pageWin.Refresh(true)
		}
	}
}

// ---------------------------------------------------------------------------
// Events
// ---------------------------------------------------------------------------

func (f *widgetsFrame) bindEvents(clearLog, exitBtn *wx.Button) {
	clearLog.Bind(wx.EVT_BUTTON, func(evt *wx.Event) { f.lboxLog.Clear() })
	exitBtn.Bind(wx.EVT_BUTTON, func(evt *wx.Event) { f.frame.Close(false) })

	f.frame.BindId(wx.EVT_MENU, wx.ID_EXIT, func(evt *wx.Event) { f.frame.Close(false) })

	f.frame.BindIdRange(wx.EVT_MENU, idGoToPage, idGoToPageLast, func(evt *wx.Event) {
		f.onGoToPage(evt)
	})

	f.frame.BindId(wx.EVT_MENU, idSetTooltip, func(evt *wx.Event) { f.onSetTooltip() })
	f.frame.BindId(wx.EVT_MENU, idSetFgColour, func(evt *wx.Event) { f.onSetFgColour() })
	f.frame.BindId(wx.EVT_MENU, idSetBgColour, func(evt *wx.Event) { f.onSetBgColour() })
	f.frame.BindId(wx.EVT_MENU, idSetPageBg, func(evt *wx.Event) { f.onSetPageBg() })
	f.frame.BindId(wx.EVT_MENU, idSetFont, func(evt *wx.Event) { f.onSetFont() })
	f.frame.BindId(wx.EVT_MENU, idEnable, func(evt *wx.Event) {
		if cmd := wx.AsCommandEvent(evt); cmd != nil {
			f.attrs.enabled = cmd.IsChecked()
			f.setUpWidget(f.currentPage())
		}
	})
	f.frame.BindId(wx.EVT_MENU, idShow, func(evt *wx.Event) {
		if cmd := wx.AsCommandEvent(evt); cmd != nil {
			f.attrs.show = cmd.IsChecked()
			f.setUpWidget(f.currentPage())
		}
	})

	f.frame.BindIdRange(wx.EVT_MENU, idBorderNone, idBorderDefault, func(evt *wx.Event) {
		f.onSetBorder(evt)
	})
	f.frame.BindIdRange(wx.EVT_MENU, idVariantNormal, idVariantLarge, func(evt *wx.Event) {
		f.onSetVariant(evt)
	})

	f.frame.BindId(wx.EVT_MENU, idLayoutDirection, func(evt *wx.Event) {
		dir := f.attrs.dir
		if dir == wx.Layout_Default {
			dir = f.frame.GetLayoutDirection()
		}
		if dir == wx.Layout_LeftToRight {
			f.attrs.dir = wx.Layout_RightToLeft
		} else {
			f.attrs.dir = wx.Layout_LeftToRight
		}
		f.setUpWidget(f.currentPage())
	})

	f.frame.BindId(wx.EVT_MENU, idGlobalBusyCursor, func(evt *wx.Event) {
		cmd := wx.AsCommandEvent(evt)
		if cmd == nil {
			return
		}
		if cmd.IsChecked() {
			wx.BeginBusyCursor()
		} else {
			wx.EndBusyCursor()
		}
	})

	f.frame.BindId(wx.EVT_MENU, idBusyCursor, func(evt *wx.Event) {
		cmd := wx.AsCommandEvent(evt)
		if cmd == nil {
			return
		}
		if cmd.IsChecked() {
			f.attrs.cursor = wx.HOURGLASS_CURSOR
		} else {
			f.attrs.cursor = nil
		}
		f.setUpWidget(f.currentPage())
	})

	f.frame.BindId(wx.EVT_MENU, idDisableAutoComplete, func(evt *wx.Event) { f.onDisableAutoComplete() })
	f.frame.BindId(wx.EVT_MENU, idAutoCompleteFixed, func(evt *wx.Event) { f.onAutoCompleteFixed() })
	f.frame.BindId(wx.EVT_MENU, idAutoCompleteFilenames, func(evt *wx.Event) { f.onAutoCompleteFilenames() })
	f.frame.BindId(wx.EVT_MENU, idAutoCompleteDirectories, func(evt *wx.Event) { f.onAutoCompleteDirectories() })
	f.frame.BindId(wx.EVT_MENU, idAutoCompleteCustom, func(evt *wx.Event) { f.doUseCustomAutoComplete(1) })
	f.frame.BindId(wx.EVT_MENU, idAutoCompleteKeyLength, func(evt *wx.Event) { f.onAutoCompleteKeyLength() })
	f.frame.BindId(wx.EVT_MENU, idTextEntrySetHint, func(evt *wx.Event) { f.onSetHint() })

	f.frame.BindIdRange(wx.EVT_UPDATE_UI, idTextEntryBegin, idTextEntryEnd-1, func(evt *wx.Event) {
		ui := wx.AsUpdateUIEvent(evt)
		if ui == nil {
			return
		}
		page := f.currentPage()
		ui.Enable(page != nil && page.textEntry() != nil)
	})

	f.frame.BindId(wx.EVT_MENU, idThemeLight, func(evt *wx.Event) { f.onTheme(idThemeLight) })
	f.frame.BindId(wx.EVT_MENU, idThemeDark, func(evt *wx.Event) { f.onTheme(idThemeDark) })
	f.frame.BindId(wx.EVT_MENU, idThemeSystem, func(evt *wx.Event) { f.onTheme(idThemeSystem) })
}

func (f *widgetsFrame) onPageChanging(evt *wx.Event) {
	be := wx.AsBookCtrlEvent(evt)
	if be == nil {
		return
	}
	// don't allow selection of entries without pages (categories)
	if f.book.GetPage(be.GetSelection()) == nil {
		be.Veto()
	}
}

// onPageChanged is WidgetsFrame::OnPageChanged().
func (f *widgetsFrame) onPageChanged(evt *wx.Event) {
	be := wx.AsBookCtrlEvent(evt)
	if be == nil {
		return
	}
	sel := be.GetSelection()

	// adjust the "Page" menu selection (only when a matching item exists: the
	// menu holds one entry per page of the "All controls" category)
	if f.menuBar != nil {
		if ptr := f.menuBar.FindItem(idGoToPage + sel); ptr != nil {
			if item := wx.MenuItemFromPtr(ptr); item != nil {
				item.Check(true)
			}
		}
	}
	if f.menuBar != nil {
		f.menuBar.Check(idBusyCursor, false)
	}

	page := f.currentPage()
	if page == nil {
		return
	}

	// create the page content on demand, otherwise the startup would create
	// hundreds of controls at once
	if !page.created {
		// The C++ code freezes the page with wxWindowUpdateLocker here; the
		// bound locker has no Delete that is safe outside its own scope, so the
		// freeze is skipped (it is a redraw optimisation only).
		page.createContent(f)
		page.created = true
		page.win.SetScrollRate(10, 10)
		page.win.FitInside()

		for _, handle := range page.widgets() {
			f.connectToWidgetEvents(handle)
		}

		page.notifyRecreate = true
	}

	f.curPage = page
	f.setUpWidget(page)

	// WidgetsFrame::OnPageChanged() lets the event propagate as well
	if evt != nil {
		evt.Skip(true)
	}
}

func (f *widgetsFrame) onGoToPage(evt *wx.Event) {
	if evt == nil {
		return
	}
	f.book.SetSelection(evt.GetId() - idGoToPage)
}

