func (f *widgetsFrame) onSetTooltip() {
	dialog := wx.NewTextEntryDialog(f.frame.Ptr(),
		"Tooltip text (may use \\n, leave empty to remove): ",
		"Widgets sample", f.attrs.tooltip, 0, -1, -1, -1, -1)
	if dialog == nil {
		return
	}
	defer dialog.Delete()

	if dialog.ShowModal() != wx.ID_OK {
		return
	}

	f.attrs.tooltip = strings.ReplaceAll(dialog.GetValue(), `\n`, "\n")
	f.setUpWidget(f.currentPage())
}

func (f *widgetsFrame) onSetFgColour() {
	page := f.currentPage()
	if page == nil {
		return
	}

	if f.attrs.colFg == nil || !f.attrs.colFg.IsOk() {
		initial := wx.NewColourEmpty()
		wx.WindowFromPtr(page.win.Ptr()).GetForegroundColour(initial.Ptr())
		f.attrs.colFg = initial
	}

	col := wx.NewColourEmpty()
	wx.GetColourFromUser(f.frame.Ptr(), f.attrs.colFg.Ptr(), col.Ptr())
	if !col.IsOk() {
		col.Delete()
		return
	}

	f.attrs.colFg = col
	f.setUpWidget(page)
}

func (f *widgetsFrame) onSetBgColour() {
	page := f.currentPage()
	if page == nil {
		return
	}

	if f.attrs.colBg == nil || !f.attrs.colBg.IsOk() {
		initial := wx.NewColourEmpty()
		wx.WindowFromPtr(page.win.Ptr()).GetBackgroundColour(initial.Ptr())
		f.attrs.colBg = initial
	}

	col := wx.NewColourEmpty()
	wx.GetColourFromUser(f.frame.Ptr(), f.attrs.colBg.Ptr(), col.Ptr())
	if !col.IsOk() {
		col.Delete()
		return
	}

	f.attrs.colBg = col
	f.setUpWidget(page)
}

func (f *widgetsFrame) onSetPageBg() {
	initial := wx.NewColourEmpty()
	wx.WindowFromPtr(f.frame.Ptr()).GetBackgroundColour(initial.Ptr())

	col := wx.NewColourEmpty()
	wx.GetColourFromUser(f.frame.Ptr(), initial.Ptr(), col.Ptr())
	if !col.IsOk() {
		col.Delete()
		return
	}

	f.attrs.colPageBg = col
	f.setUpWidget(f.currentPage())
}

func (f *widgetsFrame) onSetFont() {
	page := f.currentPage()
	if page == nil {
		return
	}

	if f.attrs.font == nil || !f.attrs.font.IsOk() {
		initial := wx.NewFontDefault()
		wx.WindowFromPtr(page.win.Ptr()).GetFont(initial.Ptr())
		f.attrs.font = initial
	}

	font := wx.NewFontDefault()
	wx.GetFontFromUser(f.frame.Ptr(), f.attrs.font.Ptr(), font.Ptr())
	if !font.IsOk() {
		font.Delete()
		return
	}

	f.attrs.font = font
	f.setUpWidget(page)
	// the best size may have changed, re-layout to show it correctly
	page.win.Layout()
}

func (f *widgetsFrame) onSetBorder(evt *wx.Event) {
	if evt == nil {
		return
	}

	var border int
	switch evt.GetId() {
	case idBorderNone:
		border = wx.BORDER_NONE
	case idBorderStatic:
		border = wx.BORDER_STATIC
	case idBorderSimple:
		border = wx.BORDER_SIMPLE
	case idBorderRaised:
		border = wx.BORDER_RAISED
	case idBorderSunken:
		border = wx.BORDER_SUNKEN
	case idBorderDouble:
		border = wx.BORDER_DOUBLE
	default:
		border = wx.BORDER_DEFAULT
	}

	f.attrs.defaultFlags = (f.attrs.defaultFlags &^ wx.BORDER_MASK) | border

	page := f.currentPage()
	if page == nil {
		return
	}
	page.recreateWidget(f)
}

func (f *widgetsFrame) onSetVariant(evt *wx.Event) {
	if evt == nil {
		return
	}

	var variant int
	switch evt.GetId() {
	case idVariantSmall:
		variant = wx.WINDOW_VARIANT_SMALL
	case idVariantMini:
		variant = wx.WINDOW_VARIANT_MINI
	case idVariantLarge:
		variant = wx.WINDOW_VARIANT_LARGE
	default:
		variant = wx.WINDOW_VARIANT_NORMAL
	}

	f.attrs.variant = variant
	f.setUpWidget(f.currentPage())
	if page := f.currentPage(); page != nil {
		page.win.Layout()
	}
}

