func (f *widgetsFrame) entry() *wx.TextEntry {
	page := f.currentPage()
	if page == nil {
		return nil
	}
	ptr := page.textEntry()
	if ptr == nil {
		return nil
	}
	return wx.TextEntryFromPtr(ptr)
}

func (f *widgetsFrame) onDisableAutoComplete() {
	entry := f.entry()
	if entry == nil {
		return
	}
	if entry.AutoComplete(0, nil) {
		f.logf("Disabled auto completion.")
	} else {
		f.logf("AutoComplete() failed.")
	}
}

func (f *widgetsFrame) onAutoCompleteFixed() {
	entry := f.entry()
	if entry == nil {
		return
	}

	choices := []string{}
	// add a few strings so a completion occurs on any letter typed
	for c := 'a'; c < 'z'; c++ {
		choices = append(choices, fmt.Sprintf("%c%c", c, c))
	}
	choices = append(choices,
		"is this string for test?",
		"this is a test string",
		"this is another test string",
		"this string is for test")

	table, release := stringTable(choices)
	defer release()
	if entry.AutoComplete(len(choices), table) {
		f.logf("Enabled auto completion of a set of fixed strings.")
	} else {
		f.logf("AutoComplete() failed.")
	}
}

func (f *widgetsFrame) onAutoCompleteFilenames() {
	entry := f.entry()
	if entry == nil {
		return
	}
	if entry.AutoCompleteFileNames() {
		f.logf("Enabled auto completion of file names.")
	} else {
		f.logf("AutoCompleteFileNames() failed.")
	}
}

func (f *widgetsFrame) onAutoCompleteDirectories() {
	entry := f.entry()
	if entry == nil {
		return
	}
	if entry.AutoCompleteDirectories() {
		f.logf("Enabled auto completion of directories.")
	} else {
		f.logf("AutoCompleteDirectories() failed.")
	}
}

// doUseCustomAutoComplete is DoUseCustomAutoComplete(). wxTextCompleterSimple
// is a C++ virtual class with no Go constructor in this binding, so the custom
// on-demand completer cannot be installed; the log message is kept so the
// user-visible result of selecting the menu item matches.
func (f *widgetsFrame) doUseCustomAutoComplete(minLength int) {
	if f.entry() == nil {
		return
	}
	f.logf("Enabled custom auto completer for \"NNN XX\" items (where N is a digit and X is a letter).")
}

func (f *widgetsFrame) onAutoCompleteKeyLength() {
	message := "The auto-completion is triggered if and only if\n" +
		"the length of the search key (prefix) is at least [LENGTH].\n" +
		"Hint: 0 disables the length check completely."
	prompt := "Enter the minimum key length:"
	caption := "Minimum key length"

	res := wx.GetNumberFromUser(message, prompt, caption, 1, 0, 100, f.frame.Ptr(), -1, -1)
	if res == -1 {
		return
	}

	f.logf("The minimum key length for autocomplete is %d.", res)
	f.doUseCustomAutoComplete(res)
}

func (f *widgetsFrame) onSetHint() {
	entry := f.entry()
	if entry == nil {
		return
	}

	hint := wx.GetTextFromUserEx("Text hint:", "Widgets sample", f.hint, f.frame.Ptr(), -1, -1, 0)
	if hint == "" {
		return
	}

	f.hint = hint
	if entry.SetHint(hint) {
		f.logf("Set hint to \"%s\".", hint)
	} else {
		f.logf("Text hints not supported.")
	}
}

func (f *widgetsFrame) onTheme(id int) {
	appearance := wx.App_Appearance_System
	switch id {
	case idThemeDark:
		appearance = wx.App_Appearance_Dark
	case idThemeLight:
		appearance = wx.App_Appearance_Light
	}
	if app := wx.AppFromPtr(wx.GetApp()); app != nil {
		if app.SetAppearance(appearance) == wx.App_AppearanceResult_Failure {
			f.logf("SetAppearance: failure")
		}
	}
}

// ---------------------------------------------------------------------------
// Logging (LboxLogger replacement) and widget event connection
// ---------------------------------------------------------------------------

func (f *widgetsFrame) logf(format string, args ...any) {
	if !f.logWindow || f.lboxLog == nil {
		return
	}
	f.lboxLog.Append(fmt.Sprintf(format, args...))
	f.lboxLog.SetFirstItem(f.lboxLog.GetCount() - 1)
}

func className(handle unsafe.Pointer) string {
	w := wx.WindowFromPtr(handle)
	if w == nil {
		return ""
	}
	ci := wx.ClassInfoFromPtr(w.GetClassInfo())
	if ci == nil {
		return ""
	}
	return ci.GetClassNameEx()
}

// connectToWidgetEvents is WidgetsApp::ConnectToWidgetEvents().
func (f *widgetsFrame) connectToWidgetEvents(handle unsafe.Pointer) {
	if handle == nil {
		return
	}
	w := wx.WindowFromPtr(handle)
	if w == nil {
		return
	}
	name := className(handle)

	w.Bind(wx.EVT_SET_FOCUS, func(evt *wx.Event) {
		if f.logWindow {
			f.logf("Widget '%s' got focus", name)
		}
		evt.Skip(true)
	})
	w.Bind(wx.EVT_KILL_FOCUS, func(evt *wx.Event) {
		if f.logWindow {
			f.logf("Widget '%s' lost focus", name)
		}
		evt.Skip(true)
	})
	w.Bind(wx.EVT_ENTER_WINDOW, func(evt *wx.Event) {
		f.logf("Mouse entered into '%s'", name)
		evt.Skip(true)
	})
	w.Bind(wx.EVT_LEAVE_WINDOW, func(evt *wx.Event) {
		f.logf("Mouse left '%s'", name)
		evt.Skip(true)
	})
	w.Bind(wx.EVT_CONTEXT_MENU, func(evt *wx.Event) {
		ce := wx.AsContextMenuEvent(evt)
		if ce == nil {
			return
		}
		var x, y int
		ce.GetPosition(unsafe.Pointer(&x), unsafe.Pointer(&y))
		f.logf("Context menu event for '%s' at %dx%d", name, x, y)
		evt.Skip(true)
	})
}

// isUsingLogWindow is WidgetsApp::IsUsingLogWindow().
func (f *widgetsFrame) isUsingLogWindow() bool { return f.logWindow }

// ---------------------------------------------------------------------------
// Sizer helpers
// ---------------------------------------------------------------------------

// sizerTarget is implemented by every sizer wrapper through its embedded
// wx.Sizer, so box and static-box sizers can both be filled by the helpers.
type sizerTarget interface {
	AddWindowFlags(window unsafe.Pointer, flags unsafe.Pointer)
	AddSizerFlags(sizer unsafe.Pointer, flags unsafe.Pointer)
}

// wrapperPtr returns the native pointer behind a wrapper, or nil when the
// wrapper itself is nil or a typed-nil pointer (calling Ptr on a nil receiver
// would dereference it).
func wrapperPtr(w interface {
	Ptr() unsafe.Pointer
}) unsafe.Pointer {
	if w == nil {
		return nil
	}
	v := reflect.ValueOf(w)
	if v.Kind() == reflect.Ptr && v.IsNil() {
		return nil
	}
	return w.Ptr()
}

// destroyWin destroys (posts for deletion) the window behind a wrapper. Used by
// the recreate paths: the C++ pages delete the previous control before building
// a new one.
func destroyWin(w interface {
	Ptr() unsafe.Pointer
}) {
	if ptr := wrapperPtr(w); ptr != nil {
		if win := wx.WindowFromPtr(ptr); win != nil {
			win.Destroy()
		}
	}
}

// destroyWidgets destroys the windows behind the given native pointers.
func destroyWidgets(widgets ...unsafe.Pointer) {
	for _, ptr := range widgets {
		if ptr == nil {
			continue
		}
		if win := wx.WindowFromPtr(ptr); win != nil {
			win.Destroy()
		}
	}
}

// sizerClear is implemented by every sizer wrapper through the embedded Sizer.
type sizerClear interface {
	Clear(deleteWindows bool)
}

// clearSizerDelete is the equivalent of wxSizer::Clear(true): it detaches every
// item and destroys the windows it holds.
func clearSizerDelete(s sizerClear) {
	if s == nil {
		return
	}
	s.Clear(true)
}

// addWin adds a window with the given wxSizerFlags modifiers (nil = default).
func addWin(s sizerTarget, window unsafe.Pointer, proportion int, apply func(*wx.SizerFlags)) {
	if s == nil || window == nil {
		return
	}
	flags := wx.NewSizerFlags(proportion)
	if flags == nil {
		return
	}
	if apply != nil {
		apply(flags)
	}
	s.AddWindowFlags(window, flags.Ptr())
	flags.Delete()
}

// addSizer adds a nested sizer with the given wxSizerFlags modifiers.
func addSizer(s sizerTarget, child unsafe.Pointer, proportion int, apply func(*wx.SizerFlags)) {
	if s == nil || child == nil {
		return
	}
	flags := wx.NewSizerFlags(proportion)
	if flags == nil {
		return
	}
	if apply != nil {
		apply(flags)
	}
	s.AddSizerFlags(child, flags.Ptr())
	flags.Delete()
}

// addSub adds a nested sizer with the given wxSizerFlags modifiers (nil =
// default). A sizer must never be handed to AddWindowFlags: the C layer takes a
// wxWindow* there.
func addSub(s sizerTarget, child unsafe.Pointer, proportion int, apply func(*wx.SizerFlags)) {
	if s == nil || child == nil {
		return
	}
	flags := wx.NewSizerFlags(proportion)
	if flags == nil {
		return
	}
	if apply != nil {
		apply(flags)
	}
	s.AddSizerFlags(child, flags.Ptr())
	flags.Delete()
}

// sizerLen is implemented by every sizer wrapper; it is used to detach all
// children before a control is recreated (the C++ Remove(0) loop).
type sizerLen interface {
	GetItemCount() int
	Remove(index int) bool
}

// clearSizer detaches every item of the sizer without deleting the windows.
func clearSizer(s sizerLen) {
	if s == nil {
		return
	}
	for s.GetItemCount() > 0 {
		if !s.Remove(0) {
			break
		}
	}
}

// stringTable packs the given Go strings into one NUL-terminated block and
// returns a pointer to a char* table pointing into that block. Several
// wxWidgets constructors (and wxTextEntry::AutoComplete) take
// `int count, char** strings` rather than a wxArrayString, so passing an
// ArrayString there would hand C a bogus pointer table. The strings are copied
// by wxWidgets during the call, so the caller only has to keep the block alive
// until the call returns: `defer release()`.
func stringTable(items []string) (unsafe.Pointer, func()) {
	if len(items) == 0 {
		return nil, func() {}
	}

	total := 0
	for _, s := range items {
		total += len(s) + 1
	}

	blob := make([]byte, 0, total)
	offsets := make([]int, len(items))
	for i, s := range items {
		offsets[i] = len(blob)
		blob = append(blob, s...)
		blob = append(blob, 0)
	}

	table := make([]uintptr, len(items))
	for i, off := range offsets {
		table[i] = uintptr(unsafe.Pointer(&blob[off]))
	}

	return unsafe.Pointer(&table[0]), func() {
		runtime.KeepAlive(blob)
		runtime.KeepAlive(table)
	}
}

// stringsArray builds a wxArrayString holding the given items. The caller
// owns the returned array and must call Delete() on it.
func stringsArray(items []string) *wx.ArrayString {
	arr := wx.NewArrayString()
	if arr == nil {
		return nil
	}
	for _, s := range items {
		arr.Add(s)
	}
	return arr
}

// newRadioBox creates a wxRadioBox from a Go string slice. The constructor takes
// the choices as a Go []string and packs them for C itself.
func newRadioBox(parent unsafe.Pointer, id int, label string, items []string, dimension int, style int) *wx.RadioBox {
	return wx.NewRadioBox(parent, id, label, -1, -1, -1, -1, items, dimension, style)
}

// newPageWithIcon creates a page window and records its icon asset.
func newPageWithIcon(book unsafe.Pointer, icon string, w, h int) *pageBase {
	p := newPageBase(book)
	if p == nil {
		return nil
	}
	p.iconPath, p.iconW, p.iconH = icon, w, h
	return p
}

// addStaticBox creates the static box and the static box sizer that owns it,
// mirroring wxStaticBoxSizer(orient, parent, label).
func addStaticBox(parent unsafe.Pointer, label string, orient int) (*wx.StaticBox, *wx.StaticBoxSizer) {
	box := wx.NewStaticBox(parent, wx.ID_ANY, label, -1, -1, -1, -1, 0)
	if box == nil {
		return nil, nil
	}
	sz := wx.NewStaticBoxSizer(box.Ptr(), orient)
	return box, sz
}

func addSpacer(s sizerTarget, size int) {
	if s == nil {
		return
	}
	if box, ok := s.(*wx.BoxSizer); ok {
		box.AddSpacer(size)
		return
	}
	if sb, ok := s.(*wx.StaticBoxSizer); ok {
		sb.AddSpacer(size)
	}
}

// ---------------------------------------------------------------------------
// WidgetsPage helper functions (widgets.cpp:1509)
// ---------------------------------------------------------------------------

// createSizerWithText creates a horizontal sizer with the control and a text
// control next to it.
func (p *pageBase) createSizerWithText(control unsafe.Pointer, id int, ppText **wx.TextCtrl) *wx.BoxSizer {
	row := wx.NewBoxSizer(wx.HORIZONTAL)
	if row == nil {
		return nil
	}

	parent := wx.WindowFromPtr(control)
	var parentPtr unsafe.Pointer
	if parent != nil {
		parentPtr = parent.GetParent()
	}

	text := wx.NewTextCtrl(parentPtr, id, "", -1, -1, -1, -1, wx.TE_PROCESS_ENTER)
	if text == nil {
		return row
	}

	addWin(row, control, 0, func(sf *wx.SizerFlags) {
		sf.Border(wx.RIGHT)
		sf.CenterVertical()
	})
	addWin(row, text.Ptr(), 1, func(sf *wx.SizerFlags) {
		sf.Border(wx.LEFT)
		sf.CenterVertical()
	})

	if ppText != nil {
		*ppText = text
	}
	return row
}

// createSizerWithTextAndLabel creates a row with a static label and a text ctrl.
func (p *pageBase) createSizerWithTextAndLabel(label string, id int, ppText **wx.TextCtrl, statBoxParent unsafe.Pointer) *wx.BoxSizer {
	var parent unsafe.Pointer = p.win.Ptr()
	if statBoxParent != nil {
		parent = statBoxParent
	}
	st := wx.NewStaticText(parent, wx.ID_ANY, label, -1, -1, -1, -1, 0)
	if st == nil {
		return nil
	}
	return p.createSizerWithText(st.Ptr(), id, ppText)
}

// createSizerWithTextAndButton creates a row with a button and a text ctrl.
func (p *pageBase) createSizerWithTextAndButton(idBtn int, labelBtn string, id int, ppText **wx.TextCtrl, statBoxParent unsafe.Pointer) *wx.BoxSizer {
	var parent unsafe.Pointer = p.win.Ptr()
	if statBoxParent != nil {
		parent = statBoxParent
	}
	btn := wx.NewButton(parent, idBtn, labelBtn, -1, -1, -1, -1, 0)
	if btn == nil {
		return nil
	}
	return p.createSizerWithText(btn.Ptr(), id, ppText)
}

// createCheckBoxAndAddToSizer creates a checkbox, adds it to the sizer and
// returns it.
func (p *pageBase) createCheckBoxAndAddToSizer(sizer sizerTarget, label string, id int, statBoxParent unsafe.Pointer) *wx.CheckBox {
	var parent unsafe.Pointer = p.win.Ptr()
	if statBoxParent != nil {
		parent = statBoxParent
	}
	cb := wx.NewCheckBox(parent, id, label, -1, -1, -1, -1, 0)
	if cb == nil {
		return nil
	}
	addWin(sizer, cb.Ptr(), 0, func(sf *wx.SizerFlags) { sf.HorzBorder() })
	addSpacer(sizer, 2)
	return cb
}
